void NativePolycentricCore::registerModule(jsi::Runtime &rt, std::shared_ptr<react::CallInvoker> callInvoker) {
    auto invoker = std::make_shared<uniffi_runtime::UniffiCallInvoker>(callInvoker);
    auto tm = std::make_shared<NativePolycentricCore>(rt, invoker);
    auto obj = rt.global().createFromHostObject(rt, tm);
    rt.global().setProperty(rt, "NativePolycentricCore", obj);
}

void NativePolycentricCore::unregisterModule(jsi::Runtime &rt) {
    uniffi::polycentric_core::registry::clearRegistry();
}

